// ── Props ─────────────────────────────────────────────────────────────────────
interface Props {
  noteCards:          NoteCard[];
  pageTitle?:         string | null;
  whiteboardGrammar?: string;
  onAnchorClick?:     (nodeId: string) => void;
  vsg?:               VisualSceneGraph;
  activeAnchorId?:    string | null;
  storageKey?:        string;
  /** Professor Lesson Planner identity — documentId + pageTruthKey +
   *  activeCanonicalUnitId, per lib/whiteboard/professorLessonPlan.ts's
   *  cache key. Falls back to storageKey/"unknown" when omitted so the
   *  planner still works for existing call sites during rollout. */
  documentId?:             string;
  pageTruthKey?:           string;
  activeCanonicalUnitId?:  string | null;
  /** The current page's classifier value (SurgeonAnnotationPlan.pageRole) —
   *  passed straight through to the Professor Lesson Planner so it teaches
   *  in a style that matches what kind of page this actually is. */
  pageTeachingType?:       string | null;
  /** Start the full Professor performance as soon as the validated plan is
   * ready. Manual Whiteboard entry leaves this false and keeps existing
   * controls unchanged. */
  autoStartProfessor?:      boolean;
  /** Lets the Reader keep the mounted playback session alive while returning
   * visual attention to the PDF for source/verbal phases. `reason` is a more
   * granular phase signal than `surface` alone (see ProfessorSurfaceReason) —
   * added for stabilization item 2's diagnosability requirement, additive to
   * the existing surface/stepId/visualNeeded fields. */
  onProfessorSurfaceChange?: (surface: ProfessorSurface, info: { stepId: number; visualNeeded: boolean; reason: ProfessorSurfaceReason }) => void;
  /** Phase B2 — stable extension points for Phase B3's Learning State
   *  wiring. Fired at the obvious moments (a teaching step begins/ends
   *  during autoplay, the lesson reaches its end) but INTENTIONALLY do
   *  nothing on their own — this component never writes to the Knowledge
   *  Graph or persists a snapshot itself. That is deliberately B3's job:
   *  merely watching a lesson play should not silently grant mastery. */
  onTeachingStepStarted?:   (stepId: number) => void;
  /** misconceptionLabel: best-effort, present only when this step's
   *  emphasisTreatment was "crossOut" — see stepMisconceptionLabel in
   *  professorTimelineEngine.ts. Phase B1's own "debunk this" signal, reused
   *  here rather than requiring new interactive checkpoint UI. */
  onTeachingStepCompleted?: (stepId: number, info?: { misconceptionLabel?: string }) => void;
  /** snapshotId: the SAME identity buildProfessorLessonCacheKey() already
   *  computes for this lesson (documentId/pageTruthKey/activeCanonicalUnitId)
   *  — a stable, reusable reference a consumer can persist onto
   *  KnowledgeNodeProgress.whiteboardSnapshotIds without re-deriving or
   *  guessing the cache-key formula itself.
   *  plan: the full ProfessorLessonPlan that just finished playing — Phase
   *  B3-3's snapshot-persistence consumer needs the real visualGrammar/
   *  plannerVersion/vsgId/teaching-step content to build a reusable semantic
   *  lesson record, not just an opaque id. This component still never
   *  persists anything itself. */
  onLessonCompleted?:       (snapshotId: string, plan: ProfessorLessonPlan) => void;
}

function mergeBounds(list: Bounds[]): Bounds | null {
  if (list.length === 0) return null;
  const x0 = Math.min(...list.map(b => b.x));
  const y0 = Math.min(...list.map(b => b.y));
  const x1 = Math.max(...list.map(b => b.x + b.w));
  const y1 = Math.max(...list.map(b => b.y + b.h));
  return { x: x0, y: y0, w: x1 - x0, h: y1 - y0 };
}

function shapeIdOf(raw: string): ReturnType<typeof createShapeId> {
  return raw as unknown as ReturnType<typeof createShapeId>;
}

function intersects(a: Bounds, b: Bounds): boolean {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

/** tldraw Agent-style visual context: a small viewport screenshot plus exact,
 * structured shape data. No unrelated PDF pages or hidden lesson steps are
 * included. */
async function captureProfessorAgentCanvas(
  editor: Editor,
  targetIdByShapeId: Map<string, string>,
  semanticRoleByShapeId: Map<string, string>,
): Promise<ProfessorAgentCanvasContext> {
  const viewport = editor.getViewportPageBounds();
  const viewportBounds = { x: viewport.x, y: viewport.y, w: viewport.w, h: viewport.h };
  const shapes = editor.getCurrentPageShapes();
  const withBounds = shapes.flatMap(shape => {
    const box = editor.getShapePageBounds(shape);
    if (!box) return [];
    const bounds = { x: box.x, y: box.y, w: box.w, h: box.h };
    let text = "";
    try {
      text = String((editor.getShapeUtil(shape) as any).getText?.(shape) ?? "").slice(0, 160);
    } catch { /* a non-text shape simply contributes no text */ }
    const shapeId = String(shape.id);
    return [{
      shape,
      bounds,
      visible: intersects(bounds, viewportBounds),
      structured: {
        shapeId,
        type: shape.type,
        bounds,
        text,
        semanticRole: semanticRoleByShapeId.get(shapeId) ?? `canvas-${shape.type}`,
        sourceTargetId: targetIdByShapeId.get(shapeId) ?? null,
        origin: shapeId.startsWith("shape:prof-agent-") ? "agent" as const : shape.isLocked ? "planner" as const : "student" as const,
      },
    }];
  });
  withBounds.sort((a, b) => Number(b.visible) - Number(a.visible));
  const structuredShapes = withBounds.slice(0, 60).map(entry => entry.structured);
  const visibleShapes = withBounds.filter(entry => entry.visible).map(entry => entry.shape);
  let screenshotBase64: string | null = null;
  if (visibleShapes.length > 0) {
    try {
      const image = await editor.toImageDataUrl(visibleShapes, {
        format: "png", bounds: viewport as any, scale: 0.45, pixelRatio: 1,
        padding: 0, background: true, darkMode: false,
      });
      const encoded = image.url.replace(/^data:image\/png;base64,/, "");
      if (encoded.length <= 900_000) screenshotBase64 = encoded;
    } catch { /* structured shape context remains sufficient fallback */ }
  }
  return { viewportBounds, shapes: structuredShapes, screenshotBase64 };
}

// Every tldraw shape id MUST start with "shape:" (createShapeId enforces
// this). A plain string-concat id like `emphasis-${primaryShapeId}` fails
// that validation and crashes the whole editor — createShapeId already
// prefixes whatever string it's given, so the primary id's own "shape:"
// prefix must be stripped first or it ends up embedded mid-string instead
// of at the start. Keyed by treatment too — a shape can carry more than one
// simultaneous emphasis (e.g. circled AND numbered), each needs its own id.
function emphasisShapeId(primaryShapeId: string, treatment: string): string {
  return String(createShapeId(`emphasis-${treatment}-${primaryShapeId.replace(/^shape:/, "")}`));
}

type EmphasisTreatment = "circle" | "underline" | "pulse" | "highlight" | "number" | "crossOut";

/** One overlay shape spec per emphasis treatment. Pure — bounds in, tldraw
 *  shape spec out, no editor access. */
function emphasisOverlaySpec(treatment: EmphasisTreatment, bounds: Bounds, sequenceNumber: number | undefined): { type: "geo" | "arrow"; x: number; y: number; props: Record<string, unknown>; opacity: number } {
  switch (treatment) {
    case "crossOut":
      // A single diagonal strike corner-to-corner — "this doesn't apply /
      // rule this out," the professor's-aside counterpart to circling
      // something worth keeping. A plain arrow shape with both arrowheads
      // suppressed reads as a drawn line, not a directional connector.
      return {
        type: "arrow", x: bounds.x, y: bounds.y,
        props: {
          kind: "arc", start: { x: 0, y: 0 }, end: { x: bounds.w, y: bounds.h },
          arrowheadStart: "none", arrowheadEnd: "none",
          size: "m", color: "red", dash: "draw",
        },
        opacity: 0.85,
      };
    case "underline":
      // A thin bar just under the box — reads as "underline this", not a
      // full second outline.
      return {
        type: "geo", x: bounds.x, y: bounds.y + bounds.h + 4,
        props: { geo: "rectangle", w: bounds.w, h: 4, fill: "solid", dash: "solid", size: "s", color: "orange" },
        opacity: 1,
      };
    case "highlight":
      // A translucent wash behind the shape — a warm color for "pay
      // attention here" (used for danger-tier/trap points), not the strong
      // orange ring reserved for the single "decisive point" circle.
      return {
        type: "geo", x: bounds.x - 6, y: bounds.y - 6,
        props: { geo: "rectangle", w: bounds.w + 12, h: bounds.h + 12, fill: "solid", color: "red", size: "m" },
        opacity: 0.22,
      };
    case "number": {
      const label = String(sequenceNumber ?? "");
      return {
        type: "geo", x: bounds.x - 14, y: bounds.y - 14,
        props: { geo: "ellipse", w: 26, h: 26, fill: "solid", color: "violet", size: "s", richText: toRichText(label), font: "sans" },
        opacity: 1,
      };
    }
    case "pulse":
    case "circle":
    default:
      // tldraw shapes are static — there is no built-in pulsing animation,
      // so "pulse" deliberately renders identically to "circle" (a ring)
      // rather than silently doing nothing. A true pulse would need an
      // external rAF loop layered outside the deterministic action model.
      return {
        type: "geo", x: bounds.x - 8, y: bounds.y - 8,
        props: { geo: "ellipse", w: bounds.w + 16, h: bounds.h + 16, fill: "none", dash: "draw", size: "m", color: "orange" },
        opacity: 1,
      };
  }
}

export default function TldrawCanvas({
  noteCards, pageTitle, whiteboardGrammar = "flow",
  onAnchorClick, vsg, activeAnchorId, storageKey,
  documentId, pageTruthKey, activeCanonicalUnitId, pageTeachingType,
  autoStartProfessor = false, onProfessorSurfaceChange,
  onTeachingStepStarted, onTeachingStepCompleted, onLessonCompleted,
}: Props) {
  const licenseKey = process.env.NEXT_PUBLIC_TLDRAW_LICENSE_KEY;
  const licenseMissingInProduction = process.env.NODE_ENV === "production" && !licenseKey;
  const DEV = process.env.NODE_ENV === "development";

  // Dev-only visible readout of [WHITEBOARD_STEP_DIAGNOSTIC] — the same
  // counts as the console log, but visible without opening devtools, so
  // "is the drawing layer actually keeping up with the narration" is a
  // glance, not a log search. Never rendered in production.
  const [stepDiagnostic, setStepDiagnostic] = useState<{
    step: number; total: number; nodeCount: number; generated: number; visible: number;
  } | null>(null);

  useEffect(() => {
    console.log("[WHITEBOARD_LICENSE_DIAGNOSTIC]", {
      licenseConfigured: Boolean(licenseKey),
      licensePrefixPresent: licenseKey?.startsWith("tldraw-") ?? false,
      nodeEnv: process.env.NODE_ENV,
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const [canvasInitFailure, setCanvasInitFailure] = useState<string | null>(null);
  const editorRef = useRef<Editor | null>(null);
  const [canvasReady, setCanvasReady] = useState(false);
  const mountCountRef = useRef(0);
  const lastCameraActionIdRef = useRef<string | null>(null);
  const lastSurfaceActionIdRef = useRef<string | null>(null);
  const cameraDiagnosticTimerRef = useRef<number | null>(null);

  // ── Fallback VSG: derive one from noteCards when no vsg prop was given.
  //    The professor engine ALWAYS operates on a VisualSceneGraph — there is
  //    no separate "paragraph card" rendering path anymore. ────────────────
  const derivedVsg = useMemo(() => {
    if (vsg && vsg.nodes.length > 0) return vsg;
    if (noteCards.length === 0) return undefined;
    const state = computeVSGState(noteCardsToCanonicalEntries(noteCards), whiteboardGrammar);
    return state.status === "ready" ? state.vsg : undefined;
  }, [vsg, noteCards, whiteboardGrammar]);

  const effectiveDocumentId = documentId ?? storageKey ?? "unknown-document";
  // Fall back through the canonical format FIRST (when the VSG at least
  // carries its own source page number), then the old VSG-content-hash
  // strategy, then a literal sentinel — every one of these is still only a
  // defensive branch for a caller that didn't pass pageTruthKey; the real
  // call site (WhiteboardPanel -> TldrawCanvas) always does.
  const effectivePageTruthKey = pageTruthKey
    ?? (derivedVsg?.sourcePageNumber != null ? buildPageTruthKey(effectiveDocumentId, derivedVsg.sourcePageNumber) : undefined)
    ?? derivedVsg?.id
    ?? "unknown-page";

  const {
    lessonPlan,
    status: lessonStatus,
    errorMessage: lessonErrorMessage,
    errorCode: lessonErrorCode,
    errorDiagnostics: lessonErrorDiagnostics,
    reanalyze,
  } = useProfessorLesson({
    vsg: derivedVsg,
    documentId: effectiveDocumentId,
    pageTruthKey: effectivePageTruthKey,
    activeCanonicalUnitId: activeCanonicalUnitId ?? null,
    pageTeachingType: pageTeachingType ?? null,
    enabled: !!derivedVsg,
  });

  // P0 stabilization: a valid lesson plan whose Director legitimately
  // decided every step is verbal-only (expository/definitional page, "don't
  // force every paragraph onto the Whiteboard" — pages/api/professor-lesson-
  // plan.ts's own instruction) previously left the canvas blank for the
  // whole lesson with no indication this was intentional, indistinguishable
  // from a broken pipeline. This is a valid pedagogical state, not an error
  // — never fabricate a diagram just to fill the canvas.
  const allStepsVerbalOnly = !!lessonPlan?.directorSteps?.length
    && lessonPlan.directorSteps.every((step) => !step.visualNeeded);

  // Every narration cache entry/in-flight fetch below is scoped to this
  // identity (see lib/speech/speechSessionIdentity.ts) — lessonId is the
  // lesson plan's own VSG content hash, so a reanalyze() that regenerates a
  // new lesson for the SAME page also gets a fresh cache namespace, and two
  // different pages/documents whose narration segments happen to reuse the
  // same local id ("seg0") can never collide.
  const speechIdentity: SpeechSessionIdentity = useMemo(() => ({
    documentId: effectiveDocumentId,
    pageNumber: derivedVsg?.sourcePageNumber ?? 0,
    pageTruthKey: effectivePageTruthKey,
    owner: SPEECH_OWNER,
    lessonId: lessonPlan?.sourceSnapshot.vsgId,
  }), [effectiveDocumentId, derivedVsg?.sourcePageNumber, effectivePageTruthKey, lessonPlan?.sourceSnapshot.vsgId]);
  const speechIdentityRef = useRef(speechIdentity);
  speechIdentityRef.current = speechIdentity;

  // ── Playback state ─────────────────────────────────────────────────────
  const [totalSteps, setTotalSteps] = useState(0);
  const [stepIndex, setStepIndexState] = useState(-1);
  const stepIndexRef = useRef(-1);
  const [isPlaying, setIsPlaying] = useState(false);
  const isPlayingRef = useRef(false);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  // The teaching canvas is READ-ONLY by default — locked while playing AND
  // while paused/finished, until the student explicitly clicks "Edit a
  // copy." A fresh lesson (new pageTruthKey/documentId/activeCanonicalUnitId
  // — see the rebuild effect below) always resets this back to false, so
  // editing access from a PRIOR page's lesson never carries over.
  const [editingEnabled, setEditingEnabled] = useState(false);
  const [speed, setSpeed] = useState<PlaybackSpeed>("normal");
  const [narrationEnabled, setNarrationEnabled] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  // Explicit lifecycle state, alongside (not replacing) isPlaying/isSpeaking
  // above — those two booleans plus ref-existence checks couldn't
  // distinguish "fetch in flight" from "was forcibly stopped by another
  // owner," which is exactly the ambiguity RC4/RC5 (Speech Engine audit)
  // exploited. See lib/speech/speechState.ts.
  const [speechState, setSpeechState] = useState<SpeechState>("idle");
  const [activeSegmentId, setActiveSegmentId] = useState<string | null>(null);

  const planRef = useRef(lessonPlan);
  planRef.current = lessonPlan;
  const vsgForColorsRef = useRef(derivedVsg);
  vsgForColorsRef.current = derivedVsg;

  const createdShapeIdsRef  = useRef<Set<string>>(new Set());
  const targetIdToShapeIdRef = useRef<Map<string, string>>(new Map());
  const shapeIdToTargetIdRef = useRef<Map<string, string>>(new Map());
  // Runtime visual-agent layer. The canonical plan remains immutable; these
  // verified actions overlay (and, for a successfully illustrated step,
  // replace) only that step's deterministic visual fallback. Keeping them in
  // a separate replayable map preserves exact Previous/Restart behavior.
  const agentActionsByStepRef = useRef<Map<number, ProfessorTeachingAction[]>>(new Map());
  const agentRevealCountByStepRef = useRef<Map<number, number>>(new Map());
  const agentLocalIdsByStepRef = useRef<Map<number, string[]>>(new Map());
  const agentAttemptedStepIdsRef = useRef<Set<number>>(new Set());
  const agentAbortRef = useRef<AbortController | null>(null);
  const agentSemanticRoleByShapeIdRef = useRef<Map<string, string>>(new Map());
  const [agentVisualStatus, setAgentVisualStatus] = useState<"idle" | "observing" | "drawing" | "inspecting" | "fallback">("idle");
  const [agentDiagnostic, setAgentDiagnostic] = useState<ProfessorAgentDiagnostic>(EMPTY_AGENT_DIAGNOSTIC);
  const onAnchorClickRef = useRef(onAnchorClick);
  useEffect(() => { onAnchorClickRef.current = onAnchorClick; }, [onAnchorClick]);
  const onProfessorSurfaceChangeRef = useRef(onProfessorSurfaceChange);
  useEffect(() => { onProfessorSurfaceChangeRef.current = onProfessorSurfaceChange; }, [onProfessorSurfaceChange]);
  const storeUnsubRef = useRef<(() => void) | null>(null);

  const focusDirectorEvidence = useCallback((stepId: number) => {
    const step = planRef.current?.directorSteps?.find(candidate => candidate.stepId === stepId);
    const sourceId = step?.sourceEvidence[0]?.sourceId;
    if (!sourceId) return;
    onAnchorClickRef.current?.(sourceId);
    useReadingFocusStore.getState().setThoughtUnit(sourceId);
  }, []);

  // ── Source color lookup. Phase 3's pedagogical role color is applied on
  //    top of this in applyStateAtStep; danger-tier source evidence remains
  //    red even when an older cached script classified it more generically. ─
  const colorForTarget = useCallback((targetId: string | undefined, fallback: string): string => {
    const v = vsgForColorsRef.current;
    if (!v || !targetId) return fallback;
    const node = v.nodes.find(n => n.sourceId === targetId);
    if (node) return TIER_COLOR[node.tier] ?? fallback;
    // targetId is an edge id for a draw-arrow action (registerAnchors below
    // registers edge.id the same way it registers a node's sourceId) — was
    // previously never reached because draw-arrow never carried a targetId
    // at all, leaving EDGE_COLOR entirely dead code and every arrow grey.
    const edge = v.edges.find(e => e.id === targetId);
    if (edge) return EDGE_COLOR[edge.kind] ?? fallback;
    return fallback;
  }, []);

  const isDangerTarget = useCallback((targetId: string | undefined): boolean => {
    const v = vsgForColorsRef.current;
    return Boolean(v && targetId && v.nodes.some(n => n.sourceId === targetId && n.tier === "danger"));
  }, []);

  // ── The ONLY function that decides what the canvas should look like at a
  //    given action index — creates/updates/deletes shapes as a diff against
  //    the pure reconstructed state, exactly like the old applyVisualStates
  //    but creation-aware (lazy) instead of opacity-only. ──────────────────
  const applyStateAtStep = useCallback((editor: Editor, index: number) => {
    const plan = planRef.current;
    if (!plan) return;
    const state = computeCanvasStateAtStep(plan.actions, index);
    const semanticStepId = resolveStepIdAtStep(plan.actions, index);

    const revealedAgentActions: ProfessorTeachingAction[] = [];
    const coveredSourceTargetsByStep = new Map<number, Set<string>>();
    for (const [agentStepId, stepActions] of agentActionsByStepRef.current) {
      if (agentStepId > semanticStepId) continue;
      const revealCount = agentRevealCountByStepRef.current.get(agentStepId) ?? 0;
      const revealed = stepActions.slice(0, revealCount);
      revealedAgentActions.push(...revealed);
      const covered = new Set(revealed.flatMap(action =>
        (action.type === "draw-freehand" || action.type === "draw-shape" || action.type === "draw-arrow" || action.type === "write") && action.targetId
          ? [action.targetId]
          : [],
      ));
      if (covered.size > 0) coveredSourceTargetsByStep.set(agentStepId, covered);
    }

    // Once Claude has produced real verified visual primitives for a step,
    // only the source concepts it explicitly grounded replace their box-based
    // deterministic fallback. An ungrounded decorative stroke can augment
    // the board, but can never hide required labels/relations.
    if (coveredSourceTargetsByStep.size > 0) {
      for (const action of plan.actions) {
        const covered = coveredSourceTargetsByStep.get(action.stepId);
        if (!covered || !("targetId" in action) || !action.targetId || !covered.has(action.targetId)) continue;
        if (action.type === "draw-shape" || action.type === "draw-freehand" || action.type === "draw-arrow" || action.type === "write") {
          state.delete(action.shapeId);
        }
      }
    }
    if (revealedAgentActions.length > 0) {
      const agentState = computeCanvasStateAtStep(revealedAgentActions, revealedAgentActions.length - 1);
      for (const [shapeId, visual] of agentState) state.set(shapeId, visual);
    }

    const wantedPrimaryIds = new Set(state.keys());
    const wantedEmphasisIds = new Set(
      Array.from(state.values()).flatMap(s => s.emphasisTreatments.map(t => emphasisShapeId(s.shapeId, t.treatment))),
    );
    const wantedIds = new Set<string>([...wantedPrimaryIds, ...wantedEmphasisIds]);

    // tldraw's own createShape(s)/updateShapes/deleteShapes each no-op
    // (silent early-return, no error) when editor.getIsReadonly() is true —
    // and this component intentionally keeps the editor readonly for most of
    // its lifetime (while playing, and always until "Edit a copy" is
    // clicked) to stop the STUDENT from dragging/editing the professor's
    // shapes. That editor-wide flag doesn't distinguish "blocked because a
    // user is interacting" from "blocked because our OWN drawing engine is
    // calling the API" — so every draw action fired during autoplay was
    // being silently swallowed by tldraw itself: our own createdShapeIdsRef
    // bookkeeping advanced (it's local state, not a query of the editor),
    // but the shapes never actually reached tldraw's store, leaving the
    // canvas visibly blank despite a fully correct teaching plan. Per-shape
    // isLocked: true (already set below) is what actually keeps the student
    // from editing THESE shapes — the editor-wide flag was redundant for
    // that purpose and actively broke programmatic drawing. Lift it only
    // for the mutations this function itself performs, then restore
    // whatever it was immediately after.
    const wasReadonly = editor.getIsReadonly();
    if (wasReadonly) editor.updateInstanceState({ isReadonly: false });

    // Remove anything that shouldn't exist yet (only fires on a backward jump).
    for (const id of Array.from(createdShapeIdsRef.current)) {
      if (!wantedIds.has(id)) {
        try { editor.deleteShapes([shapeIdOf(id)]); } catch { /* already gone */ }
        createdShapeIdsRef.current.delete(id);
      }
    }

    const creates: any[] = [];
    const updates: any[] = [];

    for (const s of state.values()) {
      const targetId = s.targetId ?? shapeIdToTargetIdRef.current.get(s.shapeId);
      const sourceColor = colorForTarget(targetId, s.kind === "arrow" ? "grey" : "blue");
      const semanticColor = colorForTeachingRole(s.teachingRole)
        ?? colorForRelationship(s.relationshipKind);
      const color = isDangerTarget(targetId) ? "red" : (semanticColor ?? sourceColor);
      const shapeSpec = toTldrawShapeSpec(s, color);
      if (!shapeSpec) continue;
      if (createdShapeIdsRef.current.has(s.shapeId)) {
        updates.push({ id: shapeIdOf(s.shapeId), type: shapeSpec.type, x: shapeSpec.x, y: shapeSpec.y, props: shapeSpec.props, opacity: s.opacity ?? 1 });
      } else {
        creates.push({ id: shapeIdOf(s.shapeId), type: shapeSpec.type, x: shapeSpec.x, y: shapeSpec.y, props: shapeSpec.props, opacity: s.opacity ?? 1, isLocked: true });
        createdShapeIdsRef.current.add(s.shapeId);
      }

      if (s.emphasized && s.bounds) {
        // One overlay shape PER treatment — a shape can be circled AND
        // numbered at once, each gets its own id so neither is dropped.
        for (const { treatment, sequenceNumber } of s.emphasisTreatments) {
          const emphId = emphasisShapeId(s.shapeId, treatment);
          const emphSpec = emphasisOverlaySpec(treatment, s.bounds, sequenceNumber);
          if (createdShapeIdsRef.current.has(emphId)) {
            updates.push({ id: shapeIdOf(emphId), type: emphSpec.type, x: emphSpec.x, y: emphSpec.y, props: emphSpec.props });
          } else {
            creates.push({ id: shapeIdOf(emphId), type: emphSpec.type, x: emphSpec.x, y: emphSpec.y, props: emphSpec.props, opacity: emphSpec.opacity, isLocked: true });
            createdShapeIdsRef.current.add(emphId);
          }
        }
      }
    }

    for (const c of creates) editor.createShape(c as any);
    if (updates.length > 0) {
      // Same unlock -> apply -> relock sequence as the prior engine: tldraw
      // does not visually repaint an update on a locked shape even though it
      // accepts the change into the store.
      editor.updateShapes(updates.map((u: any) => ({ id: u.id, type: u.type, isLocked: false })));
      editor.updateShapes(updates);
      editor.updateShapes(updates.map((u: any) => ({ id: u.id, type: u.type, isLocked: true })));
    }

    // Restore the editor-wide readonly flag to whatever it was before this
    // function's own mutations needed it lifted — see the comment above.
    if (wasReadonly) editor.updateInstanceState({ isReadonly: true });

    // Privacy-safe per-step diagnostic — no narration/label/quote text, only
    // ids and counts. The one signal previously missing to answer "narration
    // is progressing but the canvas looks blank": editorShapeCount is
    // queried directly from tldraw's OWN store (ground truth — not this
    // component's own createdShapeIdsRef bookkeeping, which could silently
    // drift from what the editor actually has), so a real discrepancy
    // between "we called createShape" and "tldraw actually has the shape"
    // is visible here, not just inferred.
    const vsgNow = vsgForColorsRef.current;
    console.log("[WHITEBOARD_STEP_DIAGNOSTIC]", {
      pageTruthKey:        plan.sourceSnapshot?.pageTruthKey ?? null,
      sceneGraphId:        vsgNow?.id ?? null,
      currentTeachingStep: semanticStepId,
      currentActionIndex:  index,
      totalTeachingSteps:  totalTeachingSteps(plan.actions),
      // "draw" actions specifically (draw-shape/draw-arrow) — a subset of
      // totalTeachingSteps, which also counts write/speak/pause/move-camera/
      // emphasize/erase actions that never create a shape on their own.
      drawActionCount:     plan.actions.filter(a => a.type === "draw-shape" || a.type === "draw-freehand" || a.type === "draw-arrow").length,
      nodeCount:           vsgNow?.nodes.length ?? 0,
      edgeCount:           vsgNow?.edges.length ?? 0,
      shapeRecordsGenerated: wantedIds.size,
      shapeRecordsCreated:   creates.length,
      currentStepShapeIds:   Array.from(state.values()).map(s => s.shapeId),
      editorShapeCount:      editor.getCurrentPageShapeIds().size,
      visibleShapeCount:     createdShapeIdsRef.current.size,
      agentVisualActionCount: revealedAgentActions.length,
    });
    if (DEV) {
      setStepDiagnostic({
        step: Math.max(semanticStepId + 1, 0), total: totalTeachingSteps(plan.actions), nodeCount: vsgNow?.nodes.length ?? 0,
        generated: wantedIds.size, visible: createdShapeIdsRef.current.size,
      });
    }

    const surfaceState = resolveProfessorSurfaceAtStep(plan.actions, index);
    if (surfaceState && surfaceState.actionId !== lastSurfaceActionIdRef.current) {
      lastSurfaceActionIdRef.current = surfaceState.actionId;
      const directorStep = plan.directorSteps?.find(step => step.stepId === surfaceState.stepId);
      onProfessorSurfaceChangeRef.current?.(surfaceState.surface, {
        stepId: surfaceState.stepId,
        visualNeeded: directorStep?.visualNeeded ?? surfaceState.surface === "whiteboard",
        reason: surfaceState.reason,
      });
    }

    const agentCameraAction = [...revealedAgentActions].reverse().find(
      (action): action is Extract<ProfessorTeachingAction, { type: "move-camera" }> => action.type === "move-camera",
    ) ?? null;
    const cameraAction = agentCameraAction ?? resolveCameraActionAtStep(plan.actions, index);
    if (cameraAction && cameraAction.actionId !== lastCameraActionIdRef.current) {
      lastCameraActionIdRef.current = cameraAction.actionId;
      const liveBounds = cameraAction.targetIds
        .map(id => editor.getShapePageBounds(shapeIdOf(id)))
        .filter((b): b is NonNullable<typeof b> => !!b)
        .map(b => ({ x: b.x, y: b.y, w: b.w, h: b.h }));
      // focusBounds comes from deterministic layout and therefore works even
      // when the active shape is about to be drawn but does not exist in the
      // tldraw store yet. Live editor bounds remain the fallback/verification.
      const merged = cameraAction.focusBounds ?? mergeBounds(liveBounds);
      if (merged) {
        // A single node's bounds are ~290x56 — a flat 40px pad on that made
        // the per-step camera crop tight enough to read as "punched in on a
        // random screenshot" rather than a professor stepping back a little
        // between points. Padding now scales with content size, with a
        // floor big enough to keep a single small node from filling the
        // whole frame, and is deliberately taller than it is wide (nodes are
        // wide/short, so the pad needs the most room on the axis the
        // content itself doesn't already fill) — the goal is "still visibly
        // zoomed to the active point" while showing meaningfully more of
        // its surrounding context than before, per rule "fit the complete
        // active teaching region, zoom only to emphasize a detail."
        const padX = Math.max(100, merged.w * 0.3);
        const padY = Math.max(140, merged.h * 1.2);
        const requestedBounds = { x: merged.x - padX, y: merged.y - padY, w: merged.w + padX * 2, h: merged.h + padY * 2 };
        const before = editor.getViewportPageBounds();
        editor.zoomToBounds(requestedBounds as any, { animation: { duration: cameraAction.durationMs } } as any);

        if (cameraDiagnosticTimerRef.current != null) window.clearTimeout(cameraDiagnosticTimerRef.current);
        console.log("[WHITEBOARD_CAMERA_DIAGNOSTIC]", {
          phase: "transition-requested",
          stepId: semanticStepId,
          actionIndex: index,
          cameraIntent: cameraAction.cameraIntent ?? "active-concept",
          activeTargetIds: cameraAction.targetIds,
          retainContextTargetIds: cameraAction.retainContextTargetIds ?? [],
          activeBounds: cameraAction.focusBounds ?? null,
          cameraBounds: requestedBounds,
          actualEditorViewport: { x: before.x, y: before.y, w: before.w, h: before.h },
          editorCamera: (editor as any).getCamera?.() ?? null,
        });
        const diagnosticActionId = cameraAction.actionId;
        cameraDiagnosticTimerRef.current = window.setTimeout(() => {
          if (lastCameraActionIdRef.current !== diagnosticActionId) return;
          const settled = editor.getViewportPageBounds();
          console.log("[WHITEBOARD_CAMERA_DIAGNOSTIC]", {
            phase: "transition-settled",
            stepId: semanticStepId,
            actionIndex: index,
            cameraIntent: cameraAction.cameraIntent ?? "active-concept",
            activeBounds: cameraAction.focusBounds ?? null,
            cameraBounds: requestedBounds,
            actualEditorViewport: { x: settled.x, y: settled.y, w: settled.w, h: settled.h },
            editorCamera: (editor as any).getCamera?.() ?? null,
          });
        }, cameraAction.durationMs + 40);
      }
    } else if (index === -1) {
      lastCameraActionIdRef.current = null;
      lastSurfaceActionIdRef.current = null;
      editor.zoomToFit();
    }

    setActiveSegmentId(resolveActiveSegmentIdAtStep(plan.actions, index));
  }, [colorForTarget, isDangerTarget]);

  const setStepIndex = useCallback((n: number) => {
    stepIndexRef.current = n;
    setStepIndexState(n);
    const editor = editorRef.current;
    if (editor) applyStateAtStep(editor, n);
  }, [applyStateAtStep]);

  const captureAgentContext = useCallback(async (editor: Editor): Promise<ProfessorAgentCanvasContext> => {
    const semanticRoles = new Map(agentSemanticRoleByShapeIdRef.current);
    for (const action of planRef.current?.actions ?? []) {
      if (action.type === "draw-shape") semanticRoles.set(action.shapeId, action.teachingRole ?? "planner-visual");
      if (action.type === "draw-arrow") semanticRoles.set(action.shapeId, action.relationshipKind ?? "planner-relationship");
      if (action.type === "write" && !semanticRoles.has(action.shapeId)) semanticRoles.set(action.shapeId, "planner-label");
    }
    return captureProfessorAgentCanvas(editor, shapeIdToTargetIdRef.current, semanticRoles);
  }, []);

  const registerRuntimeAgentActions = useCallback((actions: ProfessorTeachingAction[]) => {
    for (const action of actions) {
      if (action.type !== "draw-shape" && action.type !== "draw-freehand" && action.type !== "draw-arrow" && action.type !== "write") continue;
      agentSemanticRoleByShapeIdRef.current.set(action.shapeId, action.visualRole ?? "agent-visual");
      if (action.targetId) {
        targetIdToShapeIdRef.current.set(action.targetId, action.shapeId);
        shapeIdToTargetIdRef.current.set(action.shapeId, action.targetId);
      }
    }
  }, []);

  const revealRuntimeAgentActions = useCallback(async (
    editor: Editor,
    stepId: number,
    nextActions: ProfessorTeachingAction[],
  ): Promise<{ shapeDelta: number; nontrivialRendered: number; resultingShapeIds: string[] }> => {
    if (nextActions.length === 0) return { shapeDelta: 0, nontrivialRendered: 0, resultingShapeIds: [] };
    const beforeShapeIds = new Set(Array.from(editor.getCurrentPageShapeIds()).map(String));
    const existing = agentActionsByStepRef.current.get(stepId) ?? [];
    const start = existing.length;
    const combined = [...existing, ...nextActions];
    agentActionsByStepRef.current.set(stepId, combined);
    registerRuntimeAgentActions(nextActions);
    for (let i = 0; i < nextActions.length; i++) {
      if (planRef.current == null) return { shapeDelta: 0, nontrivialRendered: 0, resultingShapeIds: [] };
      agentRevealCountByStepRef.current.set(stepId, start + i + 1);
      applyStateAtStep(editor, stepIndexRef.current);
      const dwell = Math.min(280, Math.max(120, nextActions[i].durationMs));
      await new Promise<void>(resolve => window.setTimeout(resolve, dwell));
    }
    const afterShapeIds = new Set(Array.from(editor.getCurrentPageShapeIds()).map(String));
    const resultingShapeIds = nextActions.flatMap(action =>
      "shapeId" in action && action.shapeId && afterShapeIds.has(action.shapeId) ? [action.shapeId] : [],
    );
    const nontrivialRendered = nextActions.filter(action =>
      isNontrivialProfessorAgentAction(action)
      && "shapeId" in action && Boolean(action.shapeId)
      && afterShapeIds.has(String(action.shapeId)),
    ).length;
    return {
      shapeDelta: Array.from(afterShapeIds).filter(id => !beforeShapeIds.has(id)).length,
      nontrivialRendered,
      resultingShapeIds: Array.from(new Set(resultingShapeIds)),
    };
  }, [applyStateAtStep, registerRuntimeAgentActions]);

  /** Bounded observe/draw/inspect loop. Every pass sees the freshly rendered
   * editor state; production falls back, strict development/test stops. */
  const ensureRuntimeAgentVisualStep = useCallback(async (editor: Editor, stepId: number) => {
    const plan = planRef.current;
    if (!plan || agentAttemptedStepIdsRef.current.has(stepId)) return;
    const directorStep = plan.directorSteps?.find(step => step.stepId === stepId);
    if (!directorStep?.visualNeeded || !directorStep.focusBounds) return;
    agentAttemptedStepIdsRef.current.add(stepId);
    agentAbortRef.current?.abort();
    const controller = new AbortController();
    agentAbortRef.current = controller;
    let timedOut = false;
    const timeout = window.setTimeout(() => {
      timedOut = true;
      controller.abort();
    }, 30_000);
    const planIdentity = buildProfessorLessonCacheKey(plan.sourceSnapshot);
    const startedAt = performance.now();
    const initialEditorShapeCount = editor.getCurrentPageShapeIds().size;
    let executeActions = 0;
    let correctionActions = 0;
    let cameraCommands = 0;
    let nontrivialVisualCount = 0;
    let totalActions = 0;
    let trivialActions = 0;
    let freehandCount = 0;
    let currentPass = 0;
    setAgentDiagnostic({ ...EMPTY_AGENT_DIAGNOSTIC, eligible: true, agentTriggered: true });

    try {
      for (let passIndex = 0; passIndex < PROFESSOR_AGENT_MAX_PASSES; passIndex++) {
        currentPass = passIndex + 1;
        const pass = passIndex === 0 ? "execute" as const : "inspect" as const;
        setAgentVisualStatus(pass === "execute" ? "observing" : "inspecting");
        const updatedCanvas = await captureAgentContext(editor);
        const request = buildProfessorTldrawAgentRequest({
          plan, stepId, pass, canvas: updatedCanvas,
          priorAgentLocalIds: agentLocalIdsByStepRef.current.get(stepId) ?? [],
        });
        if (!request) throw new ProfessorAgentRequestError("visual_needed_false");
        const response = await requestProfessorTldrawAgent(request, controller.signal);
        if (buildProfessorLessonCacheKey(planRef.current?.sourceSnapshot ?? plan.sourceSnapshot) !== planIdentity) {
          throw new ProfessorAgentRequestError("aborted");
        }
        const verified = verifyProfessorTldrawAgentResponse(request, response);
        if (response.actions.length > 0 && verified.actions.length === 0) {
          throw new ProfessorAgentRequestError("verification_reject");
        }
        if (passIndex === 0) executeActions = verified.actions.length;
        else correctionActions += verified.actions.length;
        cameraCommands += verified.actions.filter(action => action.type === "move-camera").length;
        totalActions += verified.actions.length;
        trivialActions += verified.actions.filter(action => !isNontrivialProfessorAgentAction(action)).length;
        freehandCount += verified.actions.filter(action => action.type === "draw-freehand").length;
        agentLocalIdsByStepRef.current.set(stepId, [
          ...(agentLocalIdsByStepRef.current.get(stepId) ?? []), ...verified.localIds,
        ]);
        if (verified.actions.length > 0) {
          setAgentVisualStatus("drawing");
          const rendered = await revealRuntimeAgentActions(editor, stepId, verified.actions);
          nontrivialVisualCount += rendered.nontrivialRendered;
          console.log("[PROFESSOR_VISUAL_AGENT_ACTIONS]", {
            lessonId: request.identity.lessonId, stepId, pass: currentPass,
            actionTypes: verified.actions.map(action => action.type),
            actionIds: verified.actions.map(action => action.actionId),
            resultingShapeIds: rendered.resultingShapeIds,
            rejectedActionCount: verified.rejectedActionCount,
          });
        }
        setAgentDiagnostic({
          eligible: true, agentTriggered: true, currentPass, executeActions,
          correctionActions, cameraCommands, nontrivialVisualCount,
          fallbackUsed: false, fallbackReason: null,
          agentDurationMs: Math.round(performance.now() - startedAt),
          actualTldrawShapeDelta: editor.getCurrentPageShapeIds().size - initialEditorShapeCount,
          totalActions, trivialActions, freehandCount,
          visualRichnessRatio: totalActions > 0 ? nontrivialVisualCount / totalActions : 0,
        });
        if (passIndex === 0 && nontrivialVisualCount === 0) {
          throw new ProfessorAgentRequestError("no_visual_actions");
        }
        if (verified.complete && !verified.needsCorrection) break;
      }
      setAgentVisualStatus("idle");
    } catch (error) {
      const fallbackReason: ProfessorAgentFailureReason = timedOut ? "timeout"
        : error instanceof ProfessorAgentRequestError ? error.reason
          : controller.signal.aborted ? "aborted" : "network_error";
      const failure = resolveProfessorAgentFailure(PROFESSOR_AGENT_STRICT, fallbackReason);
      if (planRef.current) {
        setAgentVisualStatus("fallback");
        setAgentDiagnostic({
          eligible: true, agentTriggered: true, currentPass, executeActions,
          correctionActions, cameraCommands, nontrivialVisualCount,
          fallbackUsed: failure.fallbackUsed, fallbackReason,
          agentDurationMs: Math.round(performance.now() - startedAt),
          actualTldrawShapeDelta: editor.getCurrentPageShapeIds().size - initialEditorShapeCount,
          totalActions, trivialActions, freehandCount,
          visualRichnessRatio: totalActions > 0 ? nontrivialVisualCount / totalActions : 0,
        });
        console.warn("[PROFESSOR_VISUAL_AGENT_FALLBACK]", {
          lessonId: planIdentity, stepId, reason: fallbackReason,
        });
        if (failure.shouldStopPlayback) {
          setIsPlaying(false);
          throw error;
        }
      }
      // No verified visual actions means applyStateAtStep continues using
      // the existing deterministic layout; Professor playback never stalls.
    } finally {
      window.clearTimeout(timeout);
      if (agentAbortRef.current === controller) agentAbortRef.current = null;
    }
  }, [captureAgentContext, revealRuntimeAgentActions]);

  // ── Narration: single ordered queue, pre-buffered, advance-on-ended ──────
  // Real neural TTS (pages/api/tts.ts), falling back to browser speech only
  // when OpenAI is unavailable.
  //
  // CONFIRMED ROOT CAUSE of "speech cuts out mid-sentence between teaching
  // points": the old design advanced every action — including "speak" — on a
  // FIXED, pre-estimated durationMs timer, completely decoupled from how long
  // the fetched TTS audio actually took to play. Real neural-TTS audio
  // routinely runs longer than that estimate; when it did, the timer fired
  // anyway, moved to the next step, and called claimSpeech() for the NEXT
  // segment — which force-stops whatever audio is currently playing (by
  // design, so two DIFFERENT speech-owning components never overlap) — even
  // though it was the SAME component just moving itself along too fast.
  //
  // Fix: a "speak" action never advances on a timer. It resolves (fetches,
  // cached) and plays its own audio/utterance, and the NEXT step is only
  // triggered from that audio's own onended/onend event — advanceForPlayback
  // calls itself once playback genuinely finishes. Every OTHER action type
  // (draw/write/pause/camera/emphasize/erase) has no async completion signal
  // of its own, so those keep a fixed-duration timer, unchanged from before.
  // The upcoming segment's audio is pre-fetched in the background while the
  // current one plays, so there's no dead-air fetch gap between them.
  type ResolvedNarrationAudio =
    | { kind: "audio-url"; url: string }
    | { kind: "browser-speech"; script: string };

  const narrationCacheRef   = useRef<Map<string, ResolvedNarrationAudio>>(new Map());
  const narrationPendingRef = useRef<Map<string, Promise<ResolvedNarrationAudio | null>>>(new Map());
  const activeAudioElRef    = useRef<HTMLAudioElement | null>(null);
  const activeUtteranceRef  = useRef<SpeechSynthesisUtterance | null>(null);
  // Set by handlePlayPause's pause branch when neither ref above is populated
  // yet (this segment's TTS is still fetching). Checked by
  // playSegmentThenAdvance right before it would otherwise start audible
  // playback, so the response is loaded/registered but never auto-played
  // until Play is pressed again (RC5, Speech Engine audit).
  const pauseRequestedRef   = useRef(false);
  const stepTimerRef        = useRef<number | null>(null);
  const speedRef            = useRef<PlaybackSpeed>("normal");
  useEffect(() => { speedRef.current = speed; }, [speed]);
  const advanceForPlaybackRef = useRef<() => void>(() => {});

  // Phase B2 — refs (not deps) for the optional Learning-State extension
  // hooks, same "avoid re-creating advanceForPlayback's useCallback on every
  // parent re-render" pattern as speedRef/advanceForPlaybackRef above.
  const onTeachingStepStartedRef   = useRef(onTeachingStepStarted);
  const onTeachingStepCompletedRef = useRef(onTeachingStepCompleted);
  const onLessonCompletedRef       = useRef(onLessonCompleted);
  useEffect(() => { onTeachingStepStartedRef.current = onTeachingStepStarted; }, [onTeachingStepStarted]);
  useEffect(() => { onTeachingStepCompletedRef.current = onTeachingStepCompleted; }, [onTeachingStepCompleted]);
  useEffect(() => { onLessonCompletedRef.current = onLessonCompleted; }, [onLessonCompleted]);

  // Revokes every cached blob URL and empties both maps — called whenever
  // the lesson identity changes (rebuild effect) and on unmount, so a stale
  // entry from a PRIOR page/lesson can never be read by a NEW one even if a
  // future caller ever built the cache key wrong, and so blob URLs never
  // leak for the life of the component instance (RC1 from the Speech Engine
  // audit — this cache used to grow unbounded and was never cleared at all).
  const clearNarrationCache = useCallback(() => {
    for (const resolved of narrationCacheRef.current.values()) {
      if (resolved.kind === "audio-url") {
        try { URL.revokeObjectURL(resolved.url); } catch { /* already revoked/detached */ }
      }
    }
    narrationCacheRef.current.clear();
    narrationPendingRef.current.clear();
  }, []);

  const resolveSegmentAudio = useCallback((segment: NarrationSegment): Promise<ResolvedNarrationAudio | null> => {
    const cacheKey = buildSpeechCacheKey(speechIdentityRef.current, segment.id);
    const cached = narrationCacheRef.current.get(cacheKey);
    if (cached) return Promise.resolve(cached);
    const pending = narrationPendingRef.current.get(cacheKey);
    if (pending) return pending;

    const promise = (async (): Promise<ResolvedNarrationAudio | null> => {
      try {
        const res = await fetch("/api/tts", {
          method: "POST",
          headers: { "Content-Type": "application/json", Accept: "application/json" },
          body: JSON.stringify({ script: segment.text, voice: PROFESSOR_VOICE, format: "mp3", contentRole: segment.contentRole }),
        });
        const data = await res.json();
        let resolved: ResolvedNarrationAudio;
        if (data?.useBrowserSpeech) {
          resolved = { kind: "browser-speech", script: data.script || segment.text };
        } else if (data?.audioBase64) {
          const bin = atob(data.audioBase64);
          const arr = new Uint8Array(bin.length);
          for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
          const blob = new Blob([arr], { type: data.mimeType || "audio/mpeg" });
          resolved = { kind: "audio-url", url: URL.createObjectURL(blob) };
        } else {
          return null;
        }
        narrationCacheRef.current.set(cacheKey, resolved);
        return resolved;
      } catch {
        return null;
      } finally {
        narrationPendingRef.current.delete(cacheKey);
      }
    })();
    narrationPendingRef.current.set(cacheKey, promise);
    return promise;
  }, []);

  // Looks ahead from `fromIndex` (exclusive) for the next "speak" action's
  // segment, if any — used to pre-buffer its audio while the CURRENT segment
  // is still playing, so there's no fetch-latency gap between them.
  const findNextSegment = useCallback((fromIndex: number): NarrationSegment | null => {
    const plan = planRef.current;
    if (!plan) return null;
    for (let i = fromIndex + 1; i < plan.actions.length; i++) {
      const action = plan.actions[i];
      if (action.type === "speak") return plan.segments.find(s => s.id === action.segmentId) ?? null;
    }
    return null;
  }, []);

  // Phase B2: which teaching steps' narration has already been started (see
  // maybeEarlyStartStepNarration below) — "pending" while playing, "done"
  // once it naturally finishes. Cleared in stopNarration, the single choke
  // point every navigation action (Next/Previous/Restart/rebuild/unmount)
  // already funnels through, so a stale entry from a step the student
  // navigated away from mid-narration never lingers into a later visit.
  const stepNarrationRef = useRef<Map<string, "pending" | "done">>(new Map());

  // Plays `segment` (the action at `index`) to completion, THEN advances —
  // never on a timer. This is the only place a "speak" step's own audio is
  // created; every completion path (ended/error/stale) funnels through
  // onFinished so the timeline always continues exactly once.
  //
  // Phase B2 draw-while-teaching: `earlyStart` lets this be called BEFORE
  // the timeline's pointer has reached `index` — see
  // maybeEarlyStartStepNarration, which calls this the moment a step BEGINS
  // rather than waiting for its visual actions to finish first, so
  // narration and drawing genuinely overlap. When earlyStart is set, this
  // does NOT advance the pointer itself on completion — it only records
  // "done" and advances if the pointer has ALREADY caught up to `index` by
  // then (i.e. the narration outlasted the drawing); otherwise the visual
  // timer chain's own arrival at `index` (in advanceForPlayback) notices
  // "done" and continues immediately, with nothing left to wait for.
  const playSegmentThenAdvance = useCallback(async (
    segment: NarrationSegment, index: number, opts?: { earlyStart?: boolean; stepId?: number },
  ) => {
    const stepId = segment.id;
    if (!narrationEnabled) {
      console.log("[WHITEBOARD_NARRATION_TRACE]", { stepId, chunkIndex: index, cancelReason: "narration-disabled" });
      advanceForPlaybackRef.current();
      return;
    }

    const nextSegment = findNextSegment(index);
    if (nextSegment) resolveSegmentAudio(nextSegment); // pre-buffer — fire-and-forget, cached by segment id

    const token = claimSpeech(SPEECH_OWNER);
    setIsSpeaking(true);
    setSpeechState("loading");
    console.log("[WHITEBOARD_NARRATION_TRACE]", {
      stepId, chunkIndex: index,
      queueLength: narrationPendingRef.current.size + narrationCacheRef.current.size,
      audioStarted: false, audioEnded: false,
    });

    let resolved = await resolveSegmentAudio(segment);
    if (isSpeechStale(token)) {
      console.log("[WHITEBOARD_NARRATION_TRACE]", { stepId, chunkIndex: index, cancelReason: "superseded-by-newer-claim" });
      return;
    }
    if (!resolved) {
      // /api/tts failed outright (network error, malformed response) rather
      // than explicitly signaling useBrowserSpeech. StudySpeechPanel already
      // treats any failure the same as an explicit signal and falls back to
      // browser speech; this surface used to silently skip the segment
      // instead, leaving a mid-lesson gap with no audio and no fallback
      // (RC3, Speech Engine audit). Fall through into the same browser-speech
      // handling below, using the segment's own text.
      console.log("[WHITEBOARD_NARRATION_TRACE]", { stepId, chunkIndex: index, cancelReason: "resolve-failed", fallback: "browser-speech" });
      resolved = { kind: "browser-speech", script: segment.text };
    }

    // Two distinct completion paths, deliberately NOT merged into one
    // function gated by isSpeechStale — that was the exact bug that caused
    // narration to silently stall after its first segment: notifySpeechEnd()
    // releases this token BEFORE any later isSpeechStale(token) check can
    // run, so a check placed after it always (wrongly) sees its own just-
    // finished token as "stale" and skips advancing.
    //   - onNaturalEnd: the audio/utterance's own ended/onend event — this
    //     can ONLY fire from genuine playback completion (.pause(), which is
    //     what Pause and a forced stop both call, never raises it) — so a
    //     natural end always means "this segment truly finished," and always
    //     advances the timeline, unconditionally.
    //   - onForceStopCleanup: fired by the shared speech controller when a
    //     LATER claim or an explicit stop pauses this audio out from under
    //     it — purely visual/state cleanup, deliberately does NOT advance;
    //     whatever caused the force-stop (Next/Previous/Restart/rebuild/
    //     unmount) already decides what happens next on its own.
    let settled = false;
    const onNaturalEnd = (reason: "ended" | "error") => {
      if (settled) return;
      settled = true;
      setIsSpeaking(false);
      setSpeechState(reason === "error" ? "error" : "idle");
      activeAudioElRef.current = null;
      activeUtteranceRef.current = null;
      console.log("[WHITEBOARD_NARRATION_TRACE]", { stepId, chunkIndex: index, audioEnded: true, reason, earlyStart: !!opts?.earlyStart });
      if (opts?.earlyStart) {
        stepNarrationRef.current.set(segment.id, "done");
        // Narration outlasted the drawing — the pointer already caught up
        // to this speak action's own index and is waiting on us; continue.
        // If the pointer HASN'T arrived yet (drawing still revealing),
        // leave it be — its own arrival (advanceForPlayback) will see
        // "done" in stepNarrationRef and continue immediately on its own,
        // with nothing left to wait for.
        if (shouldAdvanceImmediatelyOnNarrationEnd(true, stepIndexRef.current, index)) advanceForPlaybackRef.current();
        return;
      }
      advanceForPlaybackRef.current();
    };
    const onForceStopCleanup = () => {
      if (settled) return;
      settled = true;
      setIsSpeaking(false);
      // "stopping", not "idle" — a LATER claim from a different owner
      // (StudySpeechPanel, or a tab-hidden stop) force-stopped this audio out
      // from under us, distinct from a deliberate rest state.
      setSpeechState("stopping");
      // Without this, isPlaying stayed stuck true — the UI kept showing "⏸
      // Pause" with nothing actually playing and no forward progress — until
      // the user manually toggled Pause/Play, which then skipped this
      // segment entirely rather than replaying it (RC4, Speech Engine audit).
      setIsPlaying(false);
      activeAudioElRef.current = null;
      activeUtteranceRef.current = null;
    };

    if (resolved.kind === "browser-speech") {
      if (typeof window === "undefined" || !("speechSynthesis" in window)) { onNaturalEnd("error"); return; }
      const utter = new SpeechSynthesisUtterance(resolved.script);
      utter.rate = PACE_TO_TTS_SPEED[segment.pace] ?? 1;
      activeUtteranceRef.current = utter;
      registerActiveUtterance(token, utter, onForceStopCleanup);
      utter.onstart = () => { notifySpeechStart(token, SPEECH_OWNER); setSpeechState("playing"); console.log("[WHITEBOARD_NARRATION_TRACE]", { stepId, chunkIndex: index, audioStarted: true }); };
      utter.onend   = () => { notifySpeechEnd(token, SPEECH_OWNER); onNaturalEnd("ended"); };
      utter.onerror = (e) => { notifySpeechError(token, SPEECH_OWNER, e.error); onNaturalEnd("error"); };
      window.speechSynthesis.speak(utter);
      if (pauseRequestedRef.current) {
        // Pause was pressed while this segment's TTS fetch (which decided
        // we're falling back to browser speech) was still in flight.
        // speechSynthesis has no "prepare paused" primitive — speak() then
        // an immediate synchronous pause() is the standard workaround, and
        // it reliably beats the async onstart event in practice (RC5,
        // Speech Engine audit).
        pauseRequestedRef.current = false;
        window.speechSynthesis.pause();
        setSpeechState("paused");
      }
      return;
    }

    const audio = new Audio(resolved.url);
    audio.playbackRate = PACE_TO_TTS_SPEED[segment.pace] ?? 1;
    activeAudioElRef.current = audio;
    registerActiveAudio(token, audio, onForceStopCleanup);
    audio.onplay  = () => { notifySpeechStart(token, SPEECH_OWNER); setSpeechState("playing"); console.log("[WHITEBOARD_NARRATION_TRACE]", { stepId, chunkIndex: index, audioStarted: true }); };
    audio.onended = () => { notifySpeechEnd(token, SPEECH_OWNER); onNaturalEnd("ended"); };
    audio.onerror = () => { notifySpeechError(token, SPEECH_OWNER, "audio-error"); onNaturalEnd("error"); };
    if (pauseRequestedRef.current) {
      // Same reasoning as the browser-speech branch above — the audio is now
      // loaded/registered (activeAudioElRef + the shared controller both
      // already hold it) but must not start until the user presses Play
      // again. A fresh Audio element is already .paused by default, so
      // handlePlayPause's resume branch picks this up naturally by calling
      // .play() on the same element (RC5, Speech Engine audit).
      pauseRequestedRef.current = false;
      setSpeechState("paused");
      return;
    }
    await audio.play().catch(() => onNaturalEnd("error"));
  }, [narrationEnabled, findNextSegment, resolveSegmentAudio]);

  // Phase B2 draw-while-teaching: called the moment advanceForPlayback
  // enters a NEW teaching step (before its visual actions have revealed
  // anything), so this step's narration starts playing WHILE the drawing
  // happens, not after. Only engages when the step has exactly one speak
  // action AND at least one visual action precedes it — a step with zero or
  // multiple speak actions (e.g. the intro step, which speaks both the
  // title and the learning objective) falls back untouched to the original
  // on-arrival behavior in advanceForPlayback, since "which one of two
  // narrations overlaps the drawing" has no single right answer.
  const maybeEarlyStartStepNarration = useCallback((stepId: number) => {
    const plan = planRef.current;
    if (!plan || !narrationEnabled) return;
    const start = stepStartIndex(plan.actions, stepId);
    const end = stepEndIndex(plan.actions, stepId);
    if (start < 0) return;
    const speakIndices: number[] = [];
    for (let i = start; i <= end; i++) if (plan.actions[i].type === "speak") speakIndices.push(i);
    if (speakIndices.length !== 1 || speakIndices[0] <= start) return;
    const speakIndex = speakIndices[0];
    const action = plan.actions[speakIndex];
    if (action.type !== "speak") return;
    const segment = plan.segments.find(s => s.id === action.segmentId);
    if (!segment) return;
    if (stepNarrationRef.current.has(segment.id)) return;

    stepNarrationRef.current.set(segment.id, "pending");
    playSegmentThenAdvance(segment, speakIndex, { earlyStart: true, stepId });
  }, [narrationEnabled, playSegmentThenAdvance]);

  // A Director step contains two speech phases under the SAME semantic
  // stepId: source reading on the PDF, then Professor explanation. Once the
  // source segment ends and the surface switches to Whiteboard, start the
  // explanation immediately while the following draw actions reveal. This
  // preserves source→explain order without waiting for the drawing to finish.
  const maybeEarlyStartVisualNarration = useCallback((fromIndex: number, stepId: number) => {
    const plan = planRef.current;
    if (!plan || !narrationEnabled) return;
    const end = stepEndIndex(plan.actions, stepId);
    for (let i = fromIndex + 1; i <= end; i++) {
      const candidate = plan.actions[i];
      if (candidate.type !== "speak") continue;
      const segment = plan.segments.find(item => item.id === candidate.segmentId);
      if (!segment || segment.contentRole !== "PROFESSOR_EXPLANATION") return;
      const hasVisualReveal = plan.actions.slice(fromIndex + 1, i).some(action =>
        action.type === "draw-shape" || action.type === "draw-freehand" || action.type === "draw-arrow" || action.type === "write" || action.type === "emphasize",
      );
      if (!hasVisualReveal || stepNarrationRef.current.has(segment.id)) return;
      stepNarrationRef.current.set(segment.id, "pending");
      playSegmentThenAdvance(segment, i, { earlyStart: true, stepId });
      return;
    }
  }, [narrationEnabled, playSegmentThenAdvance]);

  // Full stop: releases speech ownership entirely (explicit navigation —
  // Next/Previous/Restart/Show-complete/rebuild/unmount/narration-toggle-off
  // — never called for a plain Pause, which preserves position instead; see
  // handlePlayPause). Always carries an explicit reason so a cancellation is
  // traceable to what caused it, per the diagnostic contract above.
  const stopNarration = useCallback((cancelReason: string) => {
    const stepId = planRef.current?.actions[stepIndexRef.current]?.actionId ?? null;
    console.log("[WHITEBOARD_NARRATION_TRACE]", { stepId, cancelReason });
    stopAllSpeech(`whiteboard-${cancelReason}`);
    setIsSpeaking(false);
    setSpeechState("idle");
    activeAudioElRef.current = null;
    activeUtteranceRef.current = null;
    if (stepTimerRef.current != null) { window.clearTimeout(stepTimerRef.current); stepTimerRef.current = null; }
    // Phase B2: every navigation action (Next/Previous/Restart/rebuild/
    // unmount) funnels through here — the single correct point to drop any
    // in-flight early-started narration bookkeeping, so re-visiting a step
    // later always restarts its narration fresh rather than inheriting a
    // stale "pending"/"done" entry from a run that was abandoned mid-flight.
    stepNarrationRef.current.clear();
  }, []);

  // ── Anchor / One Brain sync map, rebuilt whenever the plan changes ──────
  const registerAnchors = useCallback((actions: ProfessorTeachingAction[]) => {
    const t2s = new Map<string, string>();
    const s2t = new Map<string, string>();
    for (const a of actions) {
      // "draw-arrow" carries an edge id as targetId (buildProfessorTeachingActions.ts)
      // — registering it here is what lets colorForTarget resolve an edge's
      // kind and apply EDGE_COLOR instead of always falling back to grey.
      if ((a.type === "write" || a.type === "draw-shape" || a.type === "draw-freehand" || a.type === "draw-arrow") && a.targetId && a.shapeId) {
        t2s.set(a.targetId, a.shapeId);
        s2t.set(a.shapeId, a.targetId);
      }
    }
    targetIdToShapeIdRef.current = t2s;
    shapeIdToTargetIdRef.current = s2t;
  }, []);

  // Clears every LOCKED (teaching-layer) shape currently on the canvas — the
  // student's own unlocked annotations survive. Called unconditionally
  // whenever the lesson identity changes AND whenever no valid lesson is
  // available, so a page/document/pageTruthKey mismatch — or a plan that
  // simply failed to generate — can never leave a PRIOR page's shapes (or
  // whatever tldraw's own persistenceKey happened to restore from IndexedDB)
  // visible behind the retry state. "A failure state is acceptable. A false
  // lesson from another page is not."
  const clearTeachingLayer = useCallback((editor: Editor) => {
    const existingLocked = editor.getCurrentPageShapes().filter(s => s.isLocked);
    if (existingLocked.length > 0) {
      editor.updateShapes(existingLocked.map(s => ({ id: s.id, type: s.type, isLocked: false })));
      editor.deleteShapes(existingLocked.map(s => s.id));
    }
    createdShapeIdsRef.current = new Set();
  }, []);

  // ── Rebuild: fires on every lessonPlan reference change — INCLUDING a
  //    transition to null (page change with no plan yet, or a failed/
  //    ungroundable generation). The canvas is cleared FIRST, unconditionally,
  //    before checking whether there's anything new to draw — never on a
  //    play/pause/next/previous/restart call, and never from an AI call
  //    itself (this component never calls OpenAI; useProfessorLesson already
  //    resolved the plan — or the lack of one — before this effect runs). ──
  useEffect(() => {
    const editor = editorRef.current;
    if (!editor) return;

    try {
      clearTeachingLayer(editor);
      agentAbortRef.current?.abort();
      agentAbortRef.current = null;
      agentActionsByStepRef.current.clear();
      agentRevealCountByStepRef.current.clear();
      agentLocalIdsByStepRef.current.clear();
      agentAttemptedStepIdsRef.current.clear();
      agentSemanticRoleByShapeIdRef.current.clear();
      setAgentVisualStatus("idle");
      setIsPlaying(false);
      stopNarration("rebuild");
      clearNarrationCache();
      stepIndexRef.current = -1;
      setStepIndexState(-1);
      lastCameraActionIdRef.current = null;
      lastSurfaceActionIdRef.current = null;
      if (cameraDiagnosticTimerRef.current != null) {
        window.clearTimeout(cameraDiagnosticTimerRef.current);
        cameraDiagnosticTimerRef.current = null;
      }
      setCanvasInitFailure(null);

      if (!lessonPlan) {
        // Nothing valid to draw right now (loading, or a failure the retry
        // UI is about to cover) — the canvas is genuinely blank, not holding
        // onto whatever was there before.
        setTotalSteps(0);
        return;
      }

      registerAnchors(lessonPlan.actions);
      setTotalSteps(totalTeachingSteps(lessonPlan.actions));
      applyStateAtStep(editor, -1);
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      console.error("[WHITEBOARD_CANVAS_INIT_FAILURE]", message);
      setCanvasInitFailure(message);
    }
    // A new lesson always starts read-only — see editingEnabled above.
    setEditingEnabled(false);
    editor.updateInstanceState({ isReadonly: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [lessonPlan]);

  // Keeps the editor's actual readonly flag in sync with isPlaying/
  // editingEnabled on every change — separate from the two "reset to
  // readonly" call sites above (mount, lesson change) because those fire
  // BEFORE this effect would otherwise run for the very first render.
  useEffect(() => {
    const editor = editorRef.current;
    if (!editor) return;
    editor.updateInstanceState({ isReadonly: isPlaying || !editingEnabled });
  }, [isPlaying, editingEnabled]);

  // ── Mount handler ─────────────────────────────────────────────────────────
  // Runs the SAME unconditional-clear-first sequence as the rebuild effect —
  // tldraw's own persistenceKey may have just restored shapes from IndexedDB
  // (a prior session's content for this storageKey) before React's lessonPlan
  // state is known to be valid for THIS load; those restored shapes are never
  // trusted as ground truth, only what the current, validated lessonPlan says.
  const handleMount = useCallback((editor: Editor) => {
    mountCountRef.current += 1;
    const isDuplicateMount = editor === editorRef.current;
    console.log("[WHITEBOARD_MOUNT_DIAGNOSTIC]", { mountCount: mountCountRef.current, editorIdentity: isDuplicateMount ? "same" : "different" });
    // React 18 StrictMode (next.config.js: reactStrictMode: true) double-
    // invokes onMount in dev — confirmed via the log above (mountCount
    // reaches 2 for the SAME editor instance on a normal load). Re-running
    // clearTeachingLayer + applyStateAtStep(editor, -1) a second time for an
    // editor we already fully initialized is redundant, unnecessary risk in
    // an async multi-step sequence — skip the duplicate work, but still keep
    // the ref assignment (harmless no-op when it's the same value) and the
    // listener re-subscription below, since StrictMode's real contract is
    // "effects must be safe to run twice," not "skip the second call
    // entirely" — only the parts of this callback that are NOT idempotent
    // (full state rebuild) are the ones being skipped here.
    editorRef.current = editor;
    setCanvasReady(true);
    if (!isDuplicateMount) {
      clearTeachingLayer(editor);
      // Read-only by default (see editingEnabled) — the isPlaying/editingEnabled
      // effect above can't apply this on its own for the very first mount,
      // since editorRef.current is still null when that effect's first run
      // fires (this callback is what SETS editorRef.current).
      editor.updateInstanceState({ isReadonly: true });
      if (lessonPlan) {
        registerAnchors(lessonPlan.actions);
        setTotalSteps(totalTeachingSteps(lessonPlan.actions));
        applyStateAtStep(editor, -1);
      } else {
        setTotalSteps(0);
      }
    }

    // Listener (re-)subscription is idempotent and safe to redo on a
    // duplicate mount — unlike the full clear+rebuild above, there's no
    // async multi-step sequence here to race against.
    storeUnsubRef.current?.();
    storeUnsubRef.current = editor.store.listen(
      () => {
        const selected = editor.getSelectedShapes();
        if (selected.length !== 1) return;
        const targetId = shapeIdToTargetIdRef.current.get(String(selected[0].id));
        if (targetId) {
          onAnchorClickRef.current?.(targetId);
          useReadingFocusStore.getState().setThoughtUnit(targetId);
        }
      },
      { scope: "session", source: "user" },
    );
  }, [lessonPlan, registerAnchors, applyStateAtStep, clearTeachingLayer]);

  useEffect(() => () => {
    storeUnsubRef.current?.();
    agentAbortRef.current?.abort();
    stopNarration("unmount");
    clearNarrationCache();
    if (cameraDiagnosticTimerRef.current != null) window.clearTimeout(cameraDiagnosticTimerRef.current);
  }, []);

  // ── Playback: the ONLY code that advances the timeline during Play ───────
  // A "speak" step schedules NOTHING here — playSegmentThenAdvance calls this
  // again itself once its own audio genuinely finishes (see above). Every
  // other action type has no async completion of its own, so it keeps a
  // fixed-duration dwell timer, tracked in stepTimerRef so Pause can cancel
  // it outright instead of leaving it ticking in the background.
  const advanceForPlayback = useCallback(() => {
    const plan = planRef.current;
    if (!plan) return;
    const next = stepIndexRef.current + 1;
    if (next >= plan.actions.length) { setIsPlaying(false); return; }
    setStepIndex(next);
    const action = plan.actions[next];

    // Phase B2 draw-while-teaching: the moment we enter a NEW step, try to
    // start its narration right away — the step's own visual actions (about
    // to reveal on their normal timers below/in subsequent calls) then
    // overlap real playing audio instead of racing to catch up to it later.
    if (stepStartIndex(plan.actions, action.stepId) === next) {
      if (next > 0) {
        const previousStepId = plan.actions[next - 1].stepId;
        if (previousStepId !== action.stepId) {
          const misconceptionLabel = stepMisconceptionLabel(plan.actions, previousStepId);
          onTeachingStepCompletedRef.current?.(previousStepId, misconceptionLabel ? { misconceptionLabel } : undefined);
        }
      }
      onTeachingStepStartedRef.current?.(action.stepId);
      focusDirectorEvidence(action.stepId);
      maybeEarlyStartStepNarration(action.stepId);
    }

    if (action.type === "set-surface" && action.surface === "whiteboard") {
      maybeEarlyStartVisualNarration(next, action.stepId);
      const editor = editorRef.current;
      const directorStep = plan.directorSteps?.find(step => step.stepId === action.stepId);
      const shouldRunAgent = Boolean(
        editor
        && directorStep?.visualNeeded
        && directorStep.focusBounds
        && !agentAttemptedStepIdsRef.current.has(action.stepId),
      );
      if (editor && shouldRunAgent) {
        void ensureRuntimeAgentVisualStep(editor, action.stepId).catch(() => {
          // Strict mode already stops playback and exposes the classified
          // failure in the diagnostic strip; prevent an unhandled rejection.
        }).finally(() => {
          // Pause/manual navigation may happen while Claude is inspecting.
          // Only resume this exact autoplay pointer when it is still active.
          if (isPlayingRef.current && stepIndexRef.current === next) {
            advanceForPlaybackRef.current();
          }
        });
        return;
      }
      const reason: ProfessorAgentFailureReason = !directorStep?.visualNeeded
        ? "visual_needed_false" : "not_triggered";
      setAgentDiagnostic({
        ...EMPTY_AGENT_DIAGNOSTIC,
        eligible: Boolean(directorStep?.visualNeeded && directorStep.focusBounds),
        fallbackUsed: false,
        fallbackReason: reason,
      });
    }

    if (action.type === "speak") {
      const segment = plan.segments.find(s => s.id === action.segmentId);
      if (segment) {
        const narrationState = stepNarrationRef.current.get(segment.id);
        const arrivalAction = resolveSpeakArrivalAction(narrationState);
        if (arrivalAction === "advance-immediately") {
          // Already finished early — the drawing simply took longer than
          // the narration this time. Nothing left to wait for.
          advanceForPlaybackRef.current();
          return;
        }
        if (arrivalAction === "wait-for-narration") {
          // Already playing (started early) — do NOT create a second Audio
          // element for the same segment. Its own onNaturalEnd (the
          // earlyStart branch in playSegmentThenAdvance) will notice the
          // pointer has now caught up here and advance when it finishes.
          return;
        }
        // Not early-started (multi-speak step, or narration was disabled
        // when this step began) — original on-arrival behavior, unchanged.
        playSegmentThenAdvance(segment, next);
        return;
      }
    }
    const duration = Math.max(action.durationMs, 200) / SPEED_FACTOR[speedRef.current];
    stepTimerRef.current = window.setTimeout(() => advanceForPlaybackRef.current(), duration);
  }, [setStepIndex, playSegmentThenAdvance, maybeEarlyStartStepNarration, maybeEarlyStartVisualNarration, focusDirectorEvidence, ensureRuntimeAgentVisualStep]);

  useEffect(() => { advanceForPlaybackRef.current = advanceForPlayback; }, [advanceForPlayback]);

  // P0 stabilization: previously gated on `autoStartProfessor` (true only for
  // the "Start Professor" button; false for the manual "🎨 Whiteboard" open
  // path), so a manually-opened Whiteboard mounted a canvas with zero shapes
  // and sat there until the student noticed and pressed Play — reported as
  // "modal opens, canvas completely blank." A ready lesson plan now
  // auto-starts playback regardless of which entry point opened the panel;
  // `autoStartProfessor` still distinguishes "Start Professor" (narrates
  // over the PDF, hides this modal — see pages/index.tsx's professorSurface
  // handling) from a manual open (stays visible as a modal while it plays).
  // The explicit Play/Pause button below is unaffected — pausing/restarting
  // still always works the same way regardless of how playback started.
  const autoStartedPlanRef = useRef<string | null>(null);
  useEffect(() => {
    if (!canvasReady || !lessonPlan) return;
    const planKey = buildProfessorLessonCacheKey(lessonPlan.sourceSnapshot);
    if (autoStartedPlanRef.current === planKey) return;
    autoStartedPlanRef.current = planKey;
    setNarrationEnabled(true);
    setIsPlaying(true);
    // Let the narration-enabled render commit so the current playback
    // callback sees the new setting before it resolves the first source clip.
    const timer = window.setTimeout(() => advanceForPlaybackRef.current(), 60);
    return () => window.clearTimeout(timer);
  }, [canvasReady, lessonPlan]);

  // ── Manual controls — always instant, exact-state jumps, never audio ────
  // Phase B2: Next/Previous move by TEACHING STEP (one narrated point's
  // full speak+write+draw+connect+emphasize set), not by raw micro-action —
  // see lib/whiteboard/professorTimelineEngine.ts's step-boundary helpers.
  // The underlying jump is still an exact-state applyStateAtStep(editor, n)
  // call at a single action index, same mechanism as before; only WHICH
  // index gets picked changed.
  // Phase B3: manual Next/Previous also fire the teaching-step notification
  // hooks (pure, no side effect on narration/timers) — a student who never
  // presses Play should still generate step-started/step-completed signals.
  // Deliberately does NOT call maybeEarlyStartStepNarration — manual jumps
  // stay exactly as instant/silent as before this change.
  const notifyManualStepTransition = useCallback((plan: NonNullable<typeof planRef.current>, fromIndex: number, toIndex: number) => {
    const fromStepId = fromIndex >= 0 ? resolveStepIdAtStep(plan.actions, fromIndex) : -1;
    const toStepId = resolveStepIdAtStep(plan.actions, toIndex);
    if (fromStepId === toStepId) return;
    if (fromStepId >= 0) {
      const misconceptionLabel = stepMisconceptionLabel(plan.actions, fromStepId);
      onTeachingStepCompletedRef.current?.(fromStepId, misconceptionLabel ? { misconceptionLabel } : undefined);
    }
    if (toStepId >= 0) {
      onTeachingStepStartedRef.current?.(toStepId);
      focusDirectorEvidence(toStepId);
    }
  }, [focusDirectorEvidence]);

  const handleNext = useCallback(() => {
    setIsPlaying(false);
    stopNarration("manual-next");
    const plan = planRef.current;
    if (!plan) return;
    const fromIndex = stepIndexRef.current;
    const toIndex = nextStepIndex(plan.actions, fromIndex);
    setStepIndex(toIndex);
    notifyManualStepTransition(plan, fromIndex, toIndex);
  }, [setStepIndex, stopNarration, notifyManualStepTransition]);

  const handlePrev = useCallback(() => {
    setIsPlaying(false);
    stopNarration("manual-previous");
    const plan = planRef.current;
    if (!plan) return;
    const fromIndex = stepIndexRef.current;
    const toIndex = previousStepIndex(plan.actions, fromIndex);
    setStepIndex(toIndex);
    notifyManualStepTransition(plan, fromIndex, toIndex);
  }, [setStepIndex, stopNarration, notifyManualStepTransition]);

  const handleRestart = useCallback(() => {
    stopNarration("manual-restart");
    setStepIndex(-1);
    setIsPlaying(true);
    advanceForPlayback();
  }, [setStepIndex, stopNarration, advanceForPlayback]);

  const handleShowComplete = useCallback(() => {
    setIsPlaying(false);
    stopNarration("manual-show-complete");
    const plan = planRef.current;
    if (!plan) return;
    setStepIndex(plan.actions.length - 1);
  }, [setStepIndex, stopNarration]);

  // Pause preserves position — it pauses the active audio/utterance in place
  // (never releases speech ownership, never resets currentTime) and cancels
  // any pending non-speak dwell timer, but does NOT call stopNarration (that
  // would abandon/reset the segment entirely). Resume continues the SAME
  // audio/utterance from where it left off; if paused between steps (no
  // active audio — e.g. a non-speak dwell), it simply continues the timeline
  // from the current step via advanceForPlayback.
  const handlePlayPause = useCallback(() => {
    if (isPlaying) {
      setIsPlaying(false);
      setSpeechState("paused");
      if (stepTimerRef.current != null) { window.clearTimeout(stepTimerRef.current); stepTimerRef.current = null; }
      const stepId = planRef.current?.actions[stepIndexRef.current]?.actionId ?? null;
      if (activeAudioElRef.current) {
        activeAudioElRef.current.pause();
        console.log("[WHITEBOARD_NARRATION_TRACE]", { stepId, cancelReason: "user-pause (audio position preserved)" });
      } else if (activeUtteranceRef.current && typeof window !== "undefined" && window.speechSynthesis) {
        window.speechSynthesis.pause();
        console.log("[WHITEBOARD_NARRATION_TRACE]", { stepId, cancelReason: "user-pause (utterance position preserved)" });
      } else {
        // Neither ref is populated yet — this segment's TTS is still
        // fetching. Without this, pause() was a silent no-op here and
        // playback began unconditionally the moment the fetch resolved,
        // contradicting the just-pressed Pause action (RC5, Speech Engine
        // audit). playSegmentThenAdvance checks this flag right before it
        // would otherwise start playback.
        pauseRequestedRef.current = true;
        console.log("[WHITEBOARD_NARRATION_TRACE]", { stepId, cancelReason: "user-pause (still fetching — deferred)" });
      }
      return;
    }
    const plan = planRef.current;
    const atEnd = !!plan && plan.actions.length > 0 && stepIndexRef.current >= plan.actions.length - 1;
    if (atEnd) {
      // "Play after completion must replay the entire teaching performance."
      stopNarration("restart-after-completion");
      setStepIndex(-1);
      setIsPlaying(true);
      advanceForPlayback();
      return;
    }
    setIsPlaying(true);
    if (activeAudioElRef.current) {
      activeAudioElRef.current.play().catch(() => {});
      setSpeechState("playing");
    } else if (activeUtteranceRef.current && typeof window !== "undefined" && window.speechSynthesis) {
      window.speechSynthesis.resume();
      setSpeechState("playing");
    } else if (pauseRequestedRef.current) {
      // Play was pressed again before the current segment's TTS fetch
      // finished — just clear the deferred-pause flag so
      // playSegmentThenAdvance plays normally the instant its response
      // arrives, instead of skipping ahead to the next segment.
      pauseRequestedRef.current = false;
      setSpeechState("loading");
    } else {
      advanceForPlayback();
    }
  }, [isPlaying, setStepIndex, stopNarration, advanceForPlayback]);

  // ── World -> canvas: external anchor focus selects + centers the shape ──
  useEffect(() => {
    const editor = editorRef.current;
    if (!editor) return;
    if (!activeAnchorId) { editor.selectNone(); return; }
    const sid = targetIdToShapeIdRef.current.get(activeAnchorId);
    if (!sid) return;
    const shape = editor.getShape(shapeIdOf(sid));
    if (!shape) return;
    editor.select(shapeIdOf(sid));
    const bounds = editor.getShapePageBounds(shapeIdOf(sid));
    if (bounds) editor.centerOnPoint({ x: bounds.midX, y: bounds.midY });
  }, [activeAnchorId]);

  // ── SVG export ────────────────────────────────────────────────────────────
  const handleExport = useCallback(async () => {
    const editor = editorRef.current;
    if (!editor) return;
    try {
      const shapeIds = [...editor.getCurrentPageShapeIds()];
      if (!shapeIds.length) return;
      const result = await (editor as any).getSvgString(shapeIds, { background: false });
      const svgStr: string | undefined = typeof result === "string" ? result : result?.svg;
      if (!svgStr) return;
      const blob = new Blob([svgStr], { type: "image/svg+xml" });
      const url = URL.createObjectURL(blob);
      const a = Object.assign(document.createElement("a"), { href: url, download: `${storageKey ?? "whiteboard"}.svg` });
      a.click();
      URL.revokeObjectURL(url);
    } catch {
      // export not supported — silently ignore
    }
  }, [storageKey]);

  // ── Render ────────────────────────────────────────────────────────────────
  // Phase B2: totalSteps now counts TEACHING STEPS (see totalTeachingSteps),
  // not raw actions — atEnd/the "N / total" readout must track the current
  // STEP's ordinal (stepId + 1, since stepId is assigned 0..N-1 contiguously
  // by buildProfessorTeachingActions.ts), not the raw action index.
  const atStart = stepIndex < 0;
  const currentStepId = lessonPlan ? resolveStepIdAtStep(lessonPlan.actions, stepIndex) : -1;
  const atEnd = totalSteps > 0 && currentStepId >= totalSteps - 1;

  // Phase B2: fires once per "newly reached the end" transition, however it
  // was reached (autoplay finishing, Next clicked to the end, "Show
  // complete diagram" clicked) — a single choke point rather than
  // instrumenting every one of those call sites separately. The final
  // step's own onTeachingStepCompleted never fires from the step-transition
  // logic in advanceForPlayback (there is no NEXT step to trigger that
  // comparison), so it fires here instead, immediately before
  // onLessonCompleted.
  useEffect(() => {
    if (!atEnd || !lessonPlan) return;
    if (currentStepId >= 0) {
      const misconceptionLabel = stepMisconceptionLabel(lessonPlan.actions, currentStepId);
      onTeachingStepCompletedRef.current?.(currentStepId, misconceptionLabel ? { misconceptionLabel } : undefined);
    }
    onLessonCompletedRef.current?.(buildProfessorLessonCacheKey(lessonPlan.sourceSnapshot), lessonPlan);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [atEnd]);
  const segments = lessonPlan?.segments ?? [];

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100%", minHeight: 480, background: "#0f172a" }}>

      {/* ── Controls bar ──────────────────────────────────────────────────── */}
      <div style={{ display: "flex", alignItems: "center", gap: 6, padding: "7px 12px", borderBottom: "1px solid rgba(255,255,255,0.08)", flexWrap: "wrap" }}>
        <span style={{ fontSize: 12, color: "#94a3b8", fontFamily: "monospace", flexShrink: 0 }}>
          {lessonPlan?.title || pageTitle || "Whiteboard"}
        </span>
        {agentVisualStatus !== "idle" && (
          <span style={{ fontSize: 9, color: agentVisualStatus === "fallback" ? "#94a3b8" : "#a7f3d0", fontFamily: "monospace", flexShrink: 0 }}>
            {agentVisualStatus === "observing" ? "Claude observing canvas…"
              : agentVisualStatus === "drawing" ? "Claude drawing…"
                : agentVisualStatus === "inspecting" ? "Claude inspecting result…"
                  : "Deterministic visual fallback"}
          </span>
        )}
        {/* Dev-only visible readout — see [WHITEBOARD_STEP_DIAGNOSTIC] above.
            Never rendered in production; a glance answer to "is the drawing
            layer actually keeping up with the narration," not a log search. */}
        {DEV && stepDiagnostic && (
          <span style={{ fontSize: 10, color: "#64748b", fontFamily: "monospace", flexShrink: 0 }}>
            Step {stepDiagnostic.step}/{stepDiagnostic.total} · {stepDiagnostic.nodeCount} scene nodes · {stepDiagnostic.generated} generated shapes · {stepDiagnostic.visible} visible
          </span>
        )}
        {DEV && (
          <span data-testid="professor-agent-debug-strip" style={{ fontSize: 9, color: agentDiagnostic.fallbackReason ? "#fca5a5" : "#a7f3d0", fontFamily: "monospace", flexShrink: 0 }}>
            agent eligible={String(agentDiagnostic.eligible)} triggered={String(agentDiagnostic.agentTriggered)} pass={agentDiagnostic.currentPass}/{PROFESSOR_AGENT_MAX_PASSES}
            {" · "}exec={agentDiagnostic.executeActions} correct={agentDiagnostic.correctionActions} camera={agentDiagnostic.cameraCommands}
            {" · "}nontrivial={agentDiagnostic.nontrivialVisualCount} shapeΔ={agentDiagnostic.actualTldrawShapeDelta}
            {" · "}total={agentDiagnostic.totalActions} trivial={agentDiagnostic.trivialActions} freehand={agentDiagnostic.freehandCount} richness={agentDiagnostic.visualRichnessRatio.toFixed(2)}
            {" · "}fallback={String(agentDiagnostic.fallbackUsed)} reason={agentDiagnostic.fallbackReason ?? "none"} duration={agentDiagnostic.agentDurationMs}ms
          </span>
        )}
        <span style={{ marginLeft: "auto", display: "flex", gap: 5, alignItems: "center" }}>
          {totalSteps > 0 && (
            <span style={{ fontSize: 10, color: "#475569", fontVariantNumeric: "tabular-nums", marginRight: 2 }}>
              {Math.max(currentStepId + 1, 0)} / {totalSteps}
            </span>
          )}

          <button onClick={handleRestart} title="Restart" style={BTN_MUTED}>&#x23EE;</button>
          <button onClick={handlePrev} disabled={atStart} title="Previous" style={atStart ? BTN_DISABLED : BTN_MUTED}>&#x25C4;</button>
          <button onClick={handlePlayPause} style={BTN_PRIMARY}>{isPlaying ? "⏸ Pause" : "▶ Play"}</button>
          <button onClick={handleNext} disabled={atEnd} title="Next" style={atEnd ? BTN_DISABLED : BTN_MUTED}>&#x25BA;</button>
          <button onClick={handleShowComplete} title="Show complete diagram" style={BTN_MUTED}>All</button>

          <select value={speed} onChange={e => setSpeed(e.target.value as PlaybackSpeed)} style={SELECT_STYLE} title="Speed">
            <option value="slow">Slow</option>
            <option value="normal">Normal</option>
            <option value="fast">Fast</option>
          </select>

          <button
            onClick={() => { const next = !narrationEnabled; setNarrationEnabled(next); if (!next) stopNarration("narration-muted"); }}
            title={narrationEnabled ? "Mute narration" : "Enable voice narration"}
            style={narrationEnabled ? BTN_ACTIVE : BTN_MUTED}
          >
            {isSpeaking ? "🔊" : narrationEnabled ? "🔉" : "🔇"}
          </button>

          <button onClick={handleExport} title="Export SVG" style={BTN_MUTED}>&#x2193; SVG</button>

          {/* Read-only by default (locked during playback AND while paused/
              finished) — this is the explicit, deliberate opt-in to draw on
              top of the diagram. Disabled while playing (editing mid-lesson
              would fight with the locked teaching layer's own updates) and
              once already enabled (nothing left to opt into). */}
          <button
            onClick={() => setEditingEnabled(true)}
            disabled={isPlaying || editingEnabled}
            title={editingEnabled ? "Editing enabled" : "Unlock this canvas for your own annotations"}
            style={isPlaying || editingEnabled ? BTN_DISABLED : BTN_MUTED}
          >
            {editingEnabled ? "✓ Editing" : "✎ Edit a copy"}
          </button>
        </span>
      </div>

      <div style={{ flex: 1, display: "flex", minHeight: 0 }}>
        {/* ── Canvas ────────────────────────────────────────────────────── */}
        <div style={{ flex: 1, position: "relative" }}>
          {licenseMissingInProduction ? (
            <div role="alert" style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 8, background: "#0f172a", color: "#94a3b8", fontFamily: "ui-monospace, monospace", fontSize: 13, textAlign: "center", padding: 24 }}>
              <span style={{ fontSize: 20 }}>⚠</span>
              <span>Whiteboard configuration is unavailable. Missing: tldraw license key.</span>
            </div>
          ) : (
            <Tldraw licenseKey={licenseKey} persistenceKey={storageKey || undefined} onMount={handleMount} assetUrls={TLDRAW_ASSET_URLS} />
          )}

          {!licenseMissingInProduction && canvasInitFailure && (
            <div role="alert" style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 8, zIndex: 20, background: "rgba(15,23,42,0.92)", color: "#94a3b8", fontFamily: "ui-monospace, monospace", fontSize: 13, textAlign: "center", padding: 24, pointerEvents: "none" }}>
              <span style={{ fontSize: 20 }}>⚠</span>
              <span>Whiteboard configuration is unavailable. Canvas initialization failed.</span>
            </div>
          )}

          {/* No fallback: a failed/ungroundable Professor Lesson Planner
              response shows a visible retry state, never a silently-
              substituted generic diagram — see useProfessorLesson.ts.
              clearTeachingLayer() above already guarantees the canvas holds
              no stale shapes by the time this renders; the background is
              still fully OPAQUE (not translucent) as defense-in-depth so
              nothing could show through even if that guarantee were ever
              violated by a future change. */}
          {!licenseMissingInProduction && !lessonPlan && lessonStatus === "error" && (
            <div role="alert" style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", background: "#0f172a", zIndex: 10, gap: 14, padding: 24, textAlign: "center" }}>
              <span style={{ fontSize: 20 }}>⚠</span>
              <span style={{ fontSize: 13, color: "#94a3b8", fontFamily: "ui-monospace, monospace" }}>
                {lessonErrorMessage ?? "Unable to generate Whiteboard for this page."}
              </span>
              {lessonErrorCode && (
                <span style={{ fontSize: 10, color: "#64748b", fontFamily: "ui-monospace, monospace" }}>
                  code: {lessonErrorCode}
                </span>
              )}
              {lessonErrorDiagnostics && (
                <span style={{ fontSize: 10, color: "#64748b", fontFamily: "ui-monospace, monospace" }}>
                  stage: {lessonErrorDiagnostics.failureStage}
                  {lessonErrorDiagnostics.model ? ` · model: ${lessonErrorDiagnostics.model}` : ""}
                  {` · request: ${lessonErrorDiagnostics.requestId}`}
                </span>
              )}
              <button onClick={reanalyze} style={BTN_PRIMARY}>Retry</button>
            </div>
          )}

          {!licenseMissingInProduction && !lessonPlan && lessonStatus !== "error" && (
            <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", background: "rgba(15,23,42,0.88)", zIndex: 10, gap: 16 }}>
              <span style={{ fontSize: 13, color: "#94a3b8", fontFamily: "ui-monospace, monospace" }}>
                {lessonStatus === "loading" ? "Reading the current page…" : "Preparing visual lesson…"}
              </span>
              <div style={{ display: "flex", flexDirection: "column", gap: 12, alignItems: "center", opacity: 0.35 }}>
                {[280, 220, 250].map((w, i) => (
                  <div key={i} style={{ width: w, height: 52, borderRadius: 8, background: "linear-gradient(90deg, #1e293b 25%, #334155 50%, #1e293b 75%)", backgroundSize: "200% 100%", animation: "wb-shimmer 1.4s ease-in-out infinite", animationDelay: `${i * 0.2}s` }} />
                ))}
              </div>
              <style>{`@keyframes wb-shimmer{0%{background-position:200% 0}100%{background-position:-200% 0}}`}</style>
            </div>
          )}

          {!licenseMissingInProduction && !canvasInitFailure && lessonPlan && allStepsVerbalOnly && (
            <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 10, zIndex: 5, background: "rgba(15,23,42,0.55)", color: "#94a3b8", fontFamily: "ui-monospace, monospace", fontSize: 13, textAlign: "center", padding: 24, pointerEvents: "none" }}>
              <span style={{ fontSize: 20 }}>🗣️</span>
              <span>Professor is teaching this page verbally — no diagram is needed for this section.</span>
            </div>
          )}
        </div>

        {/* ── Side transcript — the complete spoken explanation, never
              crammed into the diagram itself. ─────────────────────────── */}
        {segments.length > 0 && (
          <div style={{ width: 220, flexShrink: 0, borderLeft: "1px solid rgba(255,255,255,0.08)", background: "rgba(15,23,42,0.97)", overflowY: "auto", padding: "10px 12px" }}>
            <div style={{ fontSize: 10, color: "#64748b", textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 8 }}>Transcript</div>
            {segments.map(seg => (
              <div
                key={seg.id}
                style={{
                  fontSize: 11.5, lineHeight: 1.5, marginBottom: 10, padding: "4px 6px", borderRadius: 4,
                  color: seg.id === activeSegmentId ? "#e2e8f0" : "#64748b",
                  background: seg.id === activeSegmentId ? "rgba(96,165,250,0.12)" : "transparent",
                  borderLeft: seg.id === activeSegmentId ? "2px solid #60a5fa" : "2px solid transparent",
                }}
              >
                {seg.text}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

// ── Pure state -> tldraw shape props ─────────────────────────────────────────
function toTldrawShapeSpec(s: ShapeVisualState, color: string): { type: "geo" | "arrow" | "text" | "line" | "draw"; x: number; y: number; props: Record<string, unknown> } | null {
  const visualColor = s.visualStyle?.color ?? color;
  const visualSize = s.visualStyle?.size ?? "m";
  const visualDash = s.visualStyle?.dash ?? "draw";
  const visualFill = s.visualStyle?.fill ?? "none";
  if (s.kind === "freehand") {
    if (!s.points || s.points.length < 2) return null;
    const x = Math.min(...s.points.map(point => point.x));
    const y = Math.min(...s.points.map(point => point.y));
    const points = s.points.map(point => ({
      x: point.x - x,
      y: point.y - y,
      z: point.z ?? 0.5,
    }));
    return {
      type: "draw", x, y,
      props: {
        color: visualColor, fill: visualFill, dash: visualDash, size: visualSize,
        segments: [{ type: "free", path: b64Vecs.encodePoints(points) }],
        isComplete: true, isClosed: s.closed ?? false, isPen: s.isPen ?? true,
        scale: 1, scaleX: 1, scaleY: 1,
      },
    };
  }
  if (s.kind === "arrow") {
    if (!s.from || !s.to) return null;
    return {
      type: "arrow", x: s.from.x, y: s.from.y,
      props: {
        kind: "arc", start: { x: 0, y: 0 }, end: { x: s.to.x - s.from.x, y: s.to.y - s.from.y },
        // Phase B2 connector-obstacle-avoidance — tldraw's own native curve,
        // 0 (straight line) unless computeAvoidanceBend found a third
        // node's box in the way (see buildProfessorTeachingActions.ts).
        bend: s.bend ?? 0,
        richText: toRichText(s.text ?? ""), size: s.visualStyle?.size ?? "s", color: visualColor, dash: visualDash,
      },
    };
  }
  if (s.kind === "brace") {
    // A genuine bracket — a squared "]" (stem + two short ticks) drawn as a
    // real multi-point tldraw line shape, not a rectangle standing in for
    // one. Used today for a comparison group's column divider (see
    // buildProfessorTeachingActions.ts) — the "brace" shape kind existed in
    // the schema since v2 but nothing ever emitted it, so it always fell
    // back to a plain rectangle. Points are relative to the shape's own x/y
    // origin, per tldraw's TLLineShapeProps.
    if (!s.bounds) return null;
    const { w, h } = s.bounds;
    return {
      type: "line", x: s.bounds.x, y: s.bounds.y,
      props: {
        color: visualColor, dash: s.visualStyle?.dash ?? "dashed", size: s.visualStyle?.size ?? "s", spline: "line", scale: 1,
        points: {
          p1: { id: "p1", index: "a1", x: 0, y: 0 },
          p2: { id: "p2", index: "a2", x: w, y: 0 },
          p3: { id: "p3", index: "a3", x: w, y: h },
          p4: { id: "p4", index: "a4", x: 0, y: h },
        },
      },
    };
  }
  if (s.kind === "line") {
    // A short, thin filled bar rather than a full outline — reads as "a
    // drawn line/connector," distinct from a box/circle's outlined shape.
    if (!s.bounds) return null;
    return {
      type: "geo", x: s.bounds.x, y: s.bounds.y,
      props: { geo: "rectangle", w: s.bounds.w, h: Math.min(6, s.bounds.h), fill: s.visualStyle?.fill ?? "solid", dash: visualDash, size: s.visualStyle?.size ?? "s", color: visualColor },
    };
  }
  if (s.kind === "box" || s.kind === "circle" || s.kind === "diamond" || s.kind === "hexagon" || s.kind === "cloud") {
    if (!s.bounds) return null;
    // dash:"draw" gives tldraw's sketchy hand-drawn stroke; fill:"none" so the
    // performance reads as strokes being drawn, not solid cards being placed.
    // "diamond"/"hexagon"/"cloud" map 1:1 to tldraw's own built-in geo shapes
    // (decision points, warnings, and clinical pearls each get a real,
    // distinct SHAPE — not just a different color on an identical
    // rectangle). "brace" is handled separately above as a real line shape.
    const GEO_FOR_KIND: Record<string, string> = {
      circle: "ellipse", diamond: "diamond", hexagon: "hexagon", cloud: "cloud",
    };
    return {
      type: "geo", x: s.bounds.x, y: s.bounds.y,
      props: {
        geo: GEO_FOR_KIND[s.kind] ?? "rectangle",
        w: s.bounds.w, h: s.bounds.h,
        richText: toRichText(s.text ?? ""),
        fill: visualFill, dash: visualDash, size: visualSize, color: visualColor, font: "draw",
      },
    };
  }
  // text-only (e.g. the hand-written title) — a bare handwritten line, not
  // boxed like a node, so it visibly reads as "the professor wrote a title"
  // rather than another diagram card.
  return {
    type: "text", x: s.x ?? 0, y: s.y ?? 0,
    props: { richText: toRichText(s.text ?? ""), font: "draw", size: visualSize, color: s.visualStyle?.color ?? "black", autoSize: true, w: 300 },
  };
}
